insert into public.cidades (slug, nome, uf, regiao, descricao, lat, lng, imagem_url, site_prefeitura, aprovada) values
  ('jaragua-do-sul', 'Jaraguá do Sul', 'SC', 'Norte de Santa Catarina', 'Cidade de colonização alemã e italiana no Vale do Itapocu, conhecida pelo parque fabril, pelo empreendedorismo e por festas como a Schützenfest, que celebra o tiro esportivo, a dança e a gastronomia germânica.', -26.4851, -49.0666, '/img/cidades/jaragua-do-sul.svg', 'https://www.jaraguadosul.sc.gov.br', true),
  ('blumenau', 'Blumenau', 'SC', 'Vale do Itajaí', 'Fundada por imigrantes alemães em 1850, mantém viva a arquitetura enxaimel, a produção de cervejas artesanais e a Oktoberfest, uma das maiores festas populares do país.', -26.9194, -49.0661, '/img/cidades/blumenau.svg', 'https://www.blumenau.sc.gov.br', true),
  ('florianopolis', 'Florianópolis', 'SC', 'Grande Florianópolis', 'Capital de Santa Catarina, a Ilha da Magia reúne cultura açoriana, praias, o boi de mamão, a renda de bilro e uma cena vibrante de música, tecnologia e economia criativa.', -27.5949, -48.5482, '/img/cidades/florianopolis.svg', 'https://www.pmf.sc.gov.br', true),
  ('joinville', 'Joinville', 'SC', 'Norte de Santa Catarina', 'Maior cidade catarinense, a Cidade das Flores e das Bicicletas é polo industrial e sede do Festival de Dança de Joinville, o maior do mundo em número de participantes.', -26.3045, -48.8487, '/img/cidades/joinville.svg', 'https://www.joinville.sc.gov.br', true),
  ('curitiba', 'Curitiba', 'PR', 'Região Metropolitana de Curitiba', 'Capital do Paraná, referência em planejamento urbano, parques e teatros, com uma agenda cultural intensa que mistura tradições de imigrantes europeus e a cultura paranaense.', -25.4284, -49.2733, '/img/cidades/curitiba.svg', 'https://www.curitiba.pr.gov.br', true),
  ('ipatinga', 'Ipatinga', 'MG', 'Vale do Aço — Minas Gerais', 'Coração do Vale do Aço mineiro, cresceu ao redor da siderurgia e hoje se destaca pelo Parque Ipanema, por feiras de economia criativa e por uma agenda que valoriza a identidade do interior de Minas.', -19.4683, -42.5369, '/img/cidades/ipatinga.svg', 'https://www.ipatinga.mg.gov.br', true),
  ('porto-alegre', 'Porto Alegre', 'RS', 'Região Metropolitana de Porto Alegre', 'Capital gaúcha às margens do Guaíba, terra do chimarrão e do tradicionalismo, com forte cena literária, o Acampamento Farroupilha e uma das feiras de livro mais antigas do continente.', -30.0346, -51.2177, '/img/cidades/porto-alegre.svg', 'https://prefeitura.poa.br', true),
  ('gramado', 'Gramado', 'RS', 'Serra Gaúcha', 'Na Serra Gaúcha, de arquitetura europeia e clima frio, é destino de turismo o ano todo — do Natal Luz, o mais longo do mundo, ao Festival de Cinema.', -29.3747, -50.876, '/img/cidades/gramado.svg', 'https://www.gramado.rs.gov.br', true),
  ('rio-de-janeiro', 'Rio de Janeiro', 'RJ', 'Região Metropolitana do Rio de Janeiro', 'A Cidade Maravilhosa reúne praias, samba, o maior Réveillon do mundo em Copacabana, o Carnaval e uma agenda de grandes festivais de música e esporte.', -22.9068, -43.1729, '/img/cidades/rio-de-janeiro.svg', 'https://prefeitura.rio', true),
  ('sao-paulo', 'São Paulo', 'SP', 'Região Metropolitana de São Paulo', 'A maior metrópole do país concentra teatros, museus, a Virada Cultural, a Corrida de São Silvestre e uma diversidade cultural que reflete migrações de todo o mundo.', -23.5505, -46.6333, '/img/cidades/sao-paulo.svg', 'https://www.capital.sp.gov.br', true),
  ('paraty', 'Paraty', 'RJ', 'Costa Verde — Rio de Janeiro', 'Cidade histórica tombada, de ruas de pedra e casario colonial entre a serra e o mar, sede da Flip — Festa Literária Internacional de Paraty.', -23.2178, -44.7131, '/img/cidades/paraty.svg', 'https://www.paraty.rj.gov.br', true),
  ('campos-do-jordao', 'Campos do Jordão', 'SP', 'Serra da Mantiqueira — São Paulo', 'A "Suíça brasileira" na Serra da Mantiqueira, conhecida pelo inverno rigoroso e por sediar o Festival Internacional de Inverno, maior evento de música clássica do país.', -22.7392, -45.5915, '/img/cidades/campos-do-jordao.svg', 'https://www.camposdojordao.sp.gov.br', true),
  ('salvador', 'Salvador', 'BA', 'Região Metropolitana de Salvador', 'Primeira capital do Brasil, centro da cultura afro-brasileira: Pelourinho, capoeira, candomblé, a Festa de Iemanjá, a Lavagem do Bonfim e um dos maiores Carnavais do mundo.', -12.9777, -38.5016, '/img/cidades/salvador.svg', 'https://www.salvador.ba.gov.br', true),
  ('olinda', 'Olinda', 'PE', 'Região Metropolitana do Recife', 'Patrimônio Mundial pela Unesco, cidade do frevo e do maracatu, famosa pelos bonecos gigantes e por um Carnaval de rua tradicional e gratuito.', -8.0089, -34.8553, '/img/cidades/olinda.svg', 'https://www.olinda.pe.gov.br', true),
  ('parintins', 'Parintins', 'AM', 'Baixo Amazonas', 'Ilha no meio do Rio Amazonas, palco do Festival Folclórico de Parintins, em que os bois-bumbás Garantido e Caprichoso encenam lendas indígenas e ribeirinhas para um público de milhares no Bumbódromo.', -2.6283, -56.7358, '/img/cidades/parintins.svg', 'https://www.parintins.am.gov.br', true),
  ('ouro-preto', 'Ouro Preto', 'MG', 'Região Central de Minas Gerais', 'Primeiro sítio brasileiro reconhecido como Patrimônio Mundial, joia do barroco mineiro, das igrejas de Aleijadinho, da Semana Santa e de festivais de inverno e de literatura.', -20.3856, -43.5035, '/img/cidades/ouro-preto.svg', 'https://www.ouropreto.mg.gov.br', true)
insert into public.eventos (id, titulo, descricao, descricao_completa, categoria, formato, cidade, cidade_nome, uf, local, endereco, lat, lng, recorrencia, data_inicio, data_fim, horario, entrada, preco_texto, destaque, imagem_url, link_oficial, organizador_nome, status, criado_em) values
  ('schutzenfest-2026', '34ª Schützenfest', 'A tradicional festa do tiro esportivo, da dança e da gastronomia germânica de Jaraguá do Sul, com desfiles, bandinhas típicas e concursos de tiro ao alvo.', 'A Schützenfest resgata a cultura das sociedades de tiro trazidas pelos imigrantes alemães. Dias de programação com desfile de abertura, grupos folclóricos, praça de alimentação típica (marreco, eisbein, chucrute e cucas), chopp artesanal e o concurso que elege o Rei e a Rainha do Tiro. Entrada gratuita em vários dias; consulte a tabela oficial.', 'cultura', 'presencial', 'jaragua-do-sul', 'Jaraguá do Sul', 'SC', 'Parque Municipal de Eventos', 'Rua Prefeito Waldemar Grubba, 1447 - Vila Baependi', -26.5018, -49.0908, 'anual', '2026-10-08', '2026-10-18', 'A partir das 18h nos dias úteis; a partir das 12h aos finais de semana', 'misto', 'Gratuito em vários dias; ingressos de R$ 10 a R$ 20 nos demais', true, '/img/1122.png', 'https://www.jaraguadosul.sc.gov.br', 'Prefeitura de Jaraguá do Sul', 'aprovado', '2026-08-01T12:00:00.000Z'),
  ('novale-experience-2026', 'Novale Experience 2026', 'O maior evento de inovação e empreendedorismo do Norte catarinense, com palestras, rodadas de negócios e imersão em tecnologias emergentes.', 'Promovido pela Prefeitura de Jaraguá do Sul e pelo Centro de Inovação, reúne startups, investidores, indústria e poder público. Inclui trilhas de inteligência artificial, indústria 4.0, economia criativa e uma feira de expositores com pequenos negócios locais.', 'negocios', 'presencial', 'jaragua-do-sul', 'Jaraguá do Sul', 'SC', 'Centro de Inovação de Jaraguá do Sul', 'Rua Reinoldo Rau, 61 - Centro', -26.484, -49.0807, 'anual', '2026-11-21', '2026-11-22', '9h às 19h', 'gratuito', 'Gratuito mediante inscrição prévia', false, '/img/novale.png', 'https://www.sympla.com.br', 'Centro de Inovação de Jaraguá do Sul', 'aprovado', '2026-08-02T12:00:00.000Z'),
  ('fashion-tech-2026', 'Fashion Tech: inovar, capacitar e proteger ideias na moda', 'Palestra sobre como a tecnologia transforma o setor da moda, da criação de produtos à proteção da propriedade intelectual.', 'Encontro para empreendedores e profissionais criativos que querem incorporar tecnologia ao desenvolvimento de produtos de moda, entender as competências exigidas pelo mercado e aprender a proteger criações originais. Inclui networking com marcas autorais da região.', 'educacao', 'hibrido', 'jaragua-do-sul', 'Jaraguá do Sul', 'SC', 'Centro de Inovação (Novale)', 'Rua Reinoldo Rau, 61 - Centro', -26.484, -49.0807, null, '2026-11-13', null, '19h', 'pago', 'R$ 30', false, '/img/fashiontech.png', 'https://www.sympla.com.br', 'Novale', 'aprovado', '2026-08-03T12:00:00.000Z'),
  ('casa-inteligente-2026', 'Treinamento Casa Inteligente', 'Capacitação prática sobre automação residencial: segurança, conforto e eficiência energética com tecnologia acessível.', 'Para instaladores, revendas e curiosos, mostra como integrar câmeras, fechaduras, iluminação e sensores em uma residência conectada. Traz noções de projeto, orçamento e manutenção, com demonstração ao vivo.', 'educacao', 'hibrido', 'jaragua-do-sul', 'Jaraguá do Sul', 'SC', 'Auditório Discefone', 'Av. Getúlio Vargas, 300 - Centro', -26.4806, -49.084, null, '2026-10-22', null, '14h às 18h', 'gratuito', 'Gratuito com inscrição', false, '/img/intelbrass.png', 'https://www.sympla.com.br', 'Discefone', 'aprovado', '2026-08-04T12:00:00.000Z'),
  ('curso-oratoria-2027', 'Curso de Oratória — Turma de Verão', 'Aprenda a se expressar com clareza e confiança em apresentações, reuniões e no dia a dia.', 'Curso intensivo de comunicação e expressão para quem quer perder o medo de falar em público. Aborda estrutura de discurso, respiração, linguagem corporal e uso da voz, com exercícios práticos gravados em vídeo para autoavaliação.', 'educacao', 'presencial', 'jaragua-do-sul', 'Jaraguá do Sul', 'SC', 'Espaço Uninter - Polo Jaraguá do Sul', 'Rua Jorge Czerniewicz, 99 - Czerniewicz', -26.4791, -49.0812, null, '2027-01-18', '2027-01-20', '19h às 22h', 'pago', 'R$ 120', false, '/img/oratoria.jpg', 'https://www.sympla.com.br', 'Coletivo de Comunicação de Jaraguá', 'aprovado', '2026-08-05T12:00:00.000Z'),
  ('comedia-daqui-2026', 'Comédia Daqui — Stand-up toda quarta', 'O comedy club do Norte catarinense apresenta uma noite de stand-up com humoristas da região e convidados.', 'Toda quarta-feira o palco recebe comediantes locais testando material novo, com um headliner convidado fechando a noite. Ingressos limitados. Ambiente para maiores de 16 anos.', 'cultura', 'presencial', 'jaragua-do-sul', 'Jaraguá do Sul', 'SC', 'Tobatta Comedy Club', 'Rua Epitácio Pessoa, 415 - Centro', -26.4784, -49.0847, 'semanal', '2026-09-30', null, '20h', 'pago', 'R$ 25', false, '/img/comedia.jpg', 'https://www.sympla.com.br', 'Tobatta Comedy', 'aprovado', '2026-08-06T12:00:00.000Z'),
  ('oktoberfest-blumenau-2026', 'Oktoberfest Blumenau 2026', 'A segunda maior festa alemã do mundo: desfiles, bandinhas, chopp em metro e a tradicional dança dos tamancos.', 'Durante cerca de 18 dias, o Parque Vila Germânica recebe a Oktoberfest com pavilhões temáticos, concurso do chopp em metro, desfiles pelas ruas do centro e grupos folclóricos. A festa movimenta hotelaria, comércio e centenas de trabalhadores temporários da cidade.', 'gastronomia', 'presencial', 'blumenau', 'Blumenau', 'SC', 'Parque Vila Germânica', 'Rua Alberto Stein, 199 - Velha', -26.916, -49.0851, 'anual', '2026-10-07', '2026-10-25', 'A partir das 17h nos dias úteis; a partir das 11h aos fins de semana', 'pago', 'A partir de R$ 20; gratuito para crianças até 12 anos', true, '/img/chiseta.jpg', 'https://www.vilagermanica.com.br', 'Fundação Vila Germânica', 'aprovado', '2026-08-07T12:00:00.000Z'),
  ('festival-danca-joinville-2027', 'Festival de Dança de Joinville 2027', 'O maior festival de dança do mundo em número de participantes, com mostras competitivas, oficinas e apresentações gratuitas na rua.', 'Reconhecido pelo Guinness Book, reúne milhares de bailarinos de todo o país em ballet clássico, dança contemporânea, jazz, sapateado e danças urbanas. Além das mostras no Centreventos, há o Palco Aberto, com apresentações gratuitas em praças. Datas de 2027 previstas para julho — confirme no site oficial.', 'cultura', 'presencial', 'joinville', 'Joinville', 'SC', 'Centreventos Cau Hansen', 'Av. José Vieira, 315 - Saguaçu', -26.2925, -48.844, 'anual', '2027-07-20', '2027-07-31', 'Mostras a partir das 19h; Palco Aberto durante o dia', 'misto', 'Palco Aberto gratuito; mostras no teatro a partir de R$ 30', false, '/img/eventos/tema/danca.jpg', 'https://www.festivaldedanca.com.br', 'Instituto Festival de Dança de Joinville', 'aprovado', '2026-08-08T12:00:00.000Z'),
  ('boi-de-mamao-floripa-2026', 'Mostra de Boi de Mamão e Cultura Açoriana', 'Apresentações do folguedo tradicional da Ilha, com oficinas de confecção de bonecos e roda de conversa sobre a cultura açoriana.', 'Encontro de grupos de boi de mamão das comunidades do Ribeirão da Ilha, Santo Antônio de Lisboa e Pântano do Sul. Além das apresentações, há oficinas para crianças, feira de produtores da maricultura e cantoria de terno de reis.', 'cultura', 'presencial', 'florianopolis', 'Florianópolis', 'SC', 'Largo da Alfândega', 'Centro - Florianópolis', -27.5979, -48.5519, 'anual', '2026-11-08', '2026-11-09', '10h às 18h', 'gratuito', 'Gratuito', false, '/img/eventos/tema/boi-mamao.jpg', 'https://www.pmf.sc.gov.br', 'Fundação Cultural Franklin Cascaes', 'aprovado', '2026-08-09T12:00:00.000Z'),
  ('natal-curitiba-2026', 'Natal de Curitiba — Programação nos Parques', 'Corais, espetáculos de luz e feiras de artesanato espalhados pelos parques e pela Ópera de Arame.', 'A programação natalina de Curitiba ocupa o Parque Barigui, o Jardim Botânico e a Ópera de Arame com apresentações gratuitas de corais, projeções, presépios e a Feira de Artesanato de Natal, que reúne produtores da região metropolitana.', 'cultura', 'presencial', 'curitiba', 'Curitiba', 'PR', 'Parques e espaços culturais da cidade', 'Vários locais - consulte a programação oficial', -25.4284, -49.2733, 'anual', '2026-12-01', '2026-12-23', 'Apresentações às 20h; feiras a partir das 10h', 'gratuito', 'Gratuito', false, '/img/eventos/tema/natal-cidade.jpg', 'https://www.curitiba.pr.gov.br', 'Fundação Cultural de Curitiba', 'aprovado', '2026-08-10T12:00:00.000Z'),
  ('festival-teatro-curitiba-2027', 'Festival de Curitiba 2027', 'Um dos maiores festivais de artes cênicas do país, com mostra oficial, Fringe e espetáculos de rua por toda a cidade.', 'Por cerca de duas semanas, teatros, galpões e ruas de Curitiba recebem centenas de espetáculos nacionais e internacionais, além do Fringe, mostra aberta que revela novos grupos. Datas de 2027 previstas para março/abril — confirme no site oficial.', 'cultura', 'presencial', 'curitiba', 'Curitiba', 'PR', 'Teatros e espaços culturais de Curitiba', 'Vários locais - Curitiba', -25.4281, -49.2651, 'anual', '2027-03-23', '2027-04-04', 'Sessões ao longo do dia e da noite', 'misto', 'Fringe e rua gratuitos; mostra oficial a partir de R$ 40', false, '/img/eventos/tema/teatro.jpg', 'https://www.festivaldecuritiba.com.br', 'Fundação Cultural de Curitiba', 'aprovado', '2026-08-11T12:00:00.000Z'),
  ('feira-parque-ipanema-2026', 'Feira de Economia Criativa no Parque Ipanema', 'Feira mensal de artesãos, produtores de alimentos e food trucks no principal cartão-postal de Ipatinga.', 'Todo segundo domingo do mês, o Parque Ipanema recebe cerca de 120 expositores de artesanato, moda autoral, plantas, gastronomia e produtos agroecológicos do Vale do Aço. Há programação musical com artistas locais e espaço kids.', 'comunitario', 'presencial', 'ipatinga', 'Ipatinga', 'MG', 'Parque Ipanema', 'Av. Pedro Linhares Gomes - Horto', -19.4695, -42.5406, 'anual', '2026-10-11', null, '9h às 16h', 'gratuito', 'Gratuito', false, '/img/PARQUE-IPANEMA-FECHADA-scaled.jpg', 'https://www.ipatinga.mg.gov.br', 'Secretaria de Cultura, Esporte e Lazer de Ipatinga', 'aprovado', '2026-08-12T12:00:00.000Z'),
  ('corrida-vale-do-aco-2026', 'Corrida de Rua Vale do Aço', 'Prova de 5 km e 10 km pelas avenidas de Ipatinga, com percurso passando pelo Parque Ipanema.', 'Circuito de corrida de rua com largada no Centro e chegada no Parque Ipanema. Categorias por faixa etária, kit atleta com camiseta e medalha, e prova kids sem cronometragem. Parte da renda vai para projetos sociais esportivos da cidade.', 'esporte', 'presencial', 'ipatinga', 'Ipatinga', 'MG', 'Largada na Praça 1º de Maio', 'Centro - Ipatinga', -19.4778, -42.5271, 'anual', '2026-11-15', null, '6h30 (largada)', 'pago', 'R$ 90 (lote promocional)', false, '/img/ipatinga-parque-ipanema.jpg', 'https://www.ipatinga.mg.gov.br', 'Liga de Atletismo do Vale do Aço', 'aprovado', '2026-08-13T12:00:00.000Z'),
  ('rock-in-rio-2026', 'Rock in Rio 2026', 'Um dos maiores festivais de música do mundo, com sete dias de shows na Cidade do Rock, no Parque Olímpico.', 'A edição de 2026 acontece nos dias 4, 5, 6, 7, 11, 12 e 13 de setembro, com cerca de 190 shows e mais de 1.300 artistas nos palcos Mundo, Sunset, New Dance Order, Espaço Favela, Supernova e Global Village. Entre os headliners: Foo Fighters, Elton John, Calvin Harris, Maroon 5 e Twenty One Pilots.', 'cultura', 'presencial', 'rio-de-janeiro', 'Rio de Janeiro', 'RJ', 'Cidade do Rock — Parque Olímpico', 'Av. Embaixador Abelardo Bueno - Barra da Tijuca', -22.9783, -43.3947, null, '2026-09-04', '2026-09-13', 'Portões a partir das 14h', 'pago', 'Ingresso pista a partir de R$ 435 (meia)', true, '/img/eventos/tema/show.jpg', 'https://rockinrio.com', 'Rock World S.A.', 'aprovado', '2026-08-14T12:00:00.000Z'),
  ('reveillon-copacabana-2027', 'Réveillon de Copacabana 2026/2027', 'O maior Réveillon do mundo, reconhecido pelo Guinness: shows na areia e queima de fogos de balsas ao longo de 4 km de orla.', 'Na virada de 31 de dezembro de 2026 para 1º de janeiro de 2027, a praia de Copacabana recebe milhões de pessoas para shows gratuitos em vários palcos e uma queima de fogos de cerca de 12 minutos disparada de balsas no mar. Recomenda-se roupas brancas e chegar cedo. Programação de atrações divulgada pela Riotur entre outubro e dezembro.', 'cultura', 'presencial', 'rio-de-janeiro', 'Rio de Janeiro', 'RJ', 'Praia de Copacabana', 'Av. Atlântica - Copacabana', -22.9757, -43.1866, 'anual', '2026-12-31', '2027-01-01', 'Shows a partir das 20h; fogos à meia-noite', 'gratuito', 'Gratuito (áreas VIP e camarotes à parte)', false, '/img/eventos/tema/fogos.jpg', 'https://prefeitura.rio', 'Prefeitura do Rio de Janeiro / Riotur', 'aprovado', '2026-08-15T12:00:00.000Z'),
  ('acampamento-farroupilha-poa-2026', 'Acampamento Farroupilha 2026', 'A maior celebração da cultura gaúcha: piquetes, chama crioula, shows tradicionalistas, gastronomia campeira e oficinas — tudo gratuito.', 'De 29 de agosto a 20 de setembro, o Parque Harmonia se transforma no centro da cultura gaúcha, com mais de 120 atrações gratuitas: música tradicionalista, apresentações de CTGs, trova, chula e declamação, além de festivais que revelam novos talentos. O tema de 2026 é a herança jesuítica e guarani no Rio Grande do Sul.', 'cultura', 'presencial', 'porto-alegre', 'Porto Alegre', 'RS', 'Parque Maurício Sirotsky Sobrinho (Parque Harmonia)', 'Av. Edvaldo Pereira Paiva, 255 - Praia de Belas', -30.0402, -51.2376, 'anual', '2026-08-29', '2026-09-20', 'Programação diária a partir das 10h', 'gratuito', 'Gratuito', true, '/img/eventos/tema/virada.jpg', 'https://prefeitura.poa.br', 'Prefeitura de Porto Alegre', 'aprovado', '2026-08-16T12:00:00.000Z'),
  ('feira-do-livro-poa-2026', '72ª Feira do Livro de Porto Alegre', 'Uma das feiras de livro a céu aberto mais antigas do mundo, na Praça da Alfândega, com sessões de autógrafos, debates e programação infantil.', 'De 30 de outubro a 15 de novembro de 2026, a Praça da Alfândega recebe bancas de editoras e livrarias, o Café Literário, mesas de debate, contação de histórias e atividades para escolas. O tema desta edição é "Essência que faz histórias", e a patrona é a escritora Heloisa Pires de Lima — a primeira mulher negra a ocupar o posto.', 'educacao', 'presencial', 'porto-alegre', 'Porto Alegre', 'RS', 'Praça da Alfândega', 'Centro Histórico - Porto Alegre', -30.0296, -51.231, 'anual', '2026-10-30', '2026-11-15', '10h às 21h30', 'gratuito', 'Gratuito', false, '/img/eventos/tema/feira-livro.jpg', 'https://www.feiradolivropoa.com.br', 'Câmara Rio-Grandense do Livro', 'aprovado', '2026-08-17T12:00:00.000Z'),
  ('natal-luz-gramado-2026', 'Natal Luz de Gramado 2026', 'O festival de Natal mais longo do mundo (Guinness): 88 dias de espetáculos, desfiles e mais de 400 atrações gratuitas na Serra Gaúcha.', 'A 41ª edição acontece de 22 de outubro de 2026 a 17 de janeiro de 2027, com o tema "Quando o coração acende, o mundo se ilumina". São quatro espetáculos pagos — incluindo o Grande Desfile de Natal e o Nativitaten — e centenas de atrações gratuitas, com a Vila de Natal funcionando todos os dias das 9h às 21h.', 'cultura', 'presencial', 'gramado', 'Gramado', 'RS', 'Vários locais — Centro de Gramado e Expogramado', 'Gramado - RS', -29.3788, -50.873, 'anual', '2026-10-22', '2027-01-17', 'Vila de Natal das 9h às 21h; espetáculos à noite', 'misto', 'Atrações de rua gratuitas; espetáculos pagos a partir de R$ 90', true, '/img/eventos/tema/natal-luz.jpg', 'https://www.natalluz.com.br', 'Gramadotur', 'aprovado', '2026-08-18T12:00:00.000Z'),
  ('sao-silvestre-2026', '100ª Corrida Internacional de São Silvestre', 'A mais tradicional corrida de rua do Brasil: 15 km pelas ruas de São Paulo no último dia do ano, com elite mundial e milhares de amadores.', 'Disputada desde 1925, a São Silvestre larga e chega na Avenida Paulista no dia 31 de dezembro. O percurso de 15 km passa por pontos históricos do centro de São Paulo. A prova reúne atletas de elite internacional e mais de 30 mil corredores amadores, com pelotões separados por tempo previsto.', 'esporte', 'presencial', 'sao-paulo', 'São Paulo', 'SP', 'Largada e chegada na Avenida Paulista', 'Av. Paulista - Bela Vista', -23.5614, -46.656, 'anual', '2026-12-31', null, 'Elite feminina às 8h05; percurso geral às 9h', 'pago', 'Inscrição a partir de R$ 190', false, '/img/eventos/tema/corrida.jpg', 'https://www.saosilvestre.com.br', 'Fundação Cásper Líbero', 'aprovado', '2026-08-19T12:00:00.000Z'),
  ('virada-cultural-sp-2027', 'Virada Cultural de São Paulo 2027', '24 horas ininterruptas de shows, teatro, circo, dança e literatura em dezenas de palcos gratuitos espalhados pela cidade.', 'A Virada Cultural transforma o Centro de São Paulo e os distritos periféricos num grande circuito cultural gratuito, com atrações do amanhecer de sábado ao domingo. Palcos no Vale do Anhangabaú, na Praça da República e em CEUs de toda a cidade. Data de 2027 prevista para maio — confirme na programação oficial.', 'cultura', 'presencial', 'sao-paulo', 'São Paulo', 'SP', 'Vale do Anhangabaú e outros palcos pela cidade', 'Centro - São Paulo', -23.546, -46.637, 'anual', '2027-05-15', '2027-05-16', '24 horas ininterruptas', 'gratuito', 'Gratuito', false, '/img/eventos/tema/virada.jpg', 'https://www.capital.sp.gov.br', 'Secretaria Municipal de Cultura de São Paulo', 'aprovado', '2026-08-20T12:00:00.000Z'),
  ('flip-paraty-2027', '25ª Flip — Festa Literária Internacional de Paraty', 'A mais influente festa literária do país reúne autores brasileiros e estrangeiros no centro histórico de Paraty.', 'A Flip ocupa o Auditório da Matriz e a Casa Patrimônio, no Largo da Santa Rita, com mesas transmitidas ao vivo, além de uma extensa programação paralela — Flipinha (infantil), Flipzona (jovem) e a Casa da Cultura. Datas de 2027 previstas para julho; a edição de 2026 homenageou a poeta Orides Fontela.', 'educacao', 'presencial', 'paraty', 'Paraty', 'RJ', 'Auditório da Matriz e Casa Patrimônio', 'Centro Histórico - Paraty', -23.2191, -44.7134, 'anual', '2027-07-21', '2027-07-25', 'Mesas a partir das 10h', 'misto', 'Programação paralela gratuita; mesas principais com ingresso', false, '/img/eventos/tema/feira-livro.jpg', 'https://flip.org.br', 'Associação Casa Azul', 'aprovado', '2026-08-21T12:00:00.000Z'),
  ('festival-inverno-campos-do-jordao-2027', '57º Festival Internacional de Inverno de Campos do Jordão', 'O maior festival de música clássica da América Latina, com dezenas de concertos gratuitos na Serra da Mantiqueira.', 'Ao longo de julho, o Auditório Claudio Santoro e igrejas e espaços da cidade recebem orquestras, recitais e ópera, além de cursos para jovens instrumentistas de todo o país. A maior parte dos concertos é gratuita, com ingressos distribuídos online alguns dias antes de cada apresentação. Datas de 2027 previstas para julho.', 'cultura', 'presencial', 'campos-do-jordao', 'Campos do Jordão', 'SP', 'Auditório Claudio Santoro', 'Av. Dr. Luís Arrobas Martins, 1880 - Alto da Boa Vista', -22.7427, -45.6339, 'anual', '2027-07-03', '2027-08-01', 'Concertos às 11h e às 18h', 'misto', 'Maioria dos concertos gratuita; alguns com ingresso simbólico', false, '/img/eventos/tema/orquestra.jpg', 'https://www.osesp.art.br', 'Governo do Estado de São Paulo / Fundação Osesp', 'aprovado', '2026-08-22T12:00:00.000Z'),
  ('festival-parintins-2027', 'Festival Folclórico de Parintins 2027', 'A disputa entre os bois Garantido (vermelho) e Caprichoso (azul) transforma a ilha em uma ópera amazônica a céu aberto no Bumbódromo.', 'Nas últimas noites de junho, o Bumbódromo recebe três noites de apresentações em que cada boi encena lendas indígenas, ritmos e alegorias gigantes, avaliados por um júri em 21 itens. É a maior manifestação da cultura do Norte do país e move toda a economia de Parintins. Datas de 2027 previstas para o fim de junho.', 'cultura', 'presencial', 'parintins', 'Parintins', 'AM', 'Centro Cultural e Esportivo Amazonino Mendes (Bumbódromo)', 'Parintins - AM', -2.6335, -56.7374, 'anual', '2027-06-25', '2027-06-27', 'Apresentações a partir das 21h', 'pago', 'Arquibancada a partir de R$ 60; áreas populares gratuitas por ordem de chegada', true, '/img/eventos/tema/parintins.jpg', 'https://cultura.am.gov.br', 'Governo do Amazonas / Prefeitura de Parintins', 'aprovado', '2026-08-23T12:00:00.000Z'),
  ('festa-iemanja-salvador-2027', 'Festa de Iemanjá 2027', 'No 2 de fevereiro, milhares de fiéis levam flores e presentes à Rainha do Mar na Colônia de Pescadores do Rio Vermelho.', 'Uma das mais importantes celebrações afro-brasileiras: desde o amanhecer, pescadores e devotos formam filas para entregar oferendas que serão levadas ao mar em barcos. O dia é de música, cortejos e barracas pelo bairro do Rio Vermelho, unindo religiosidade e cultura popular.', 'comunitario', 'presencial', 'salvador', 'Salvador', 'BA', 'Casa do Peso — Colônia de Pescadores Z-1', 'Largo de Santana - Rio Vermelho', -13.0101, -38.49, 'anual', '2027-02-02', null, 'A partir das 5h; cortejo ao mar ao entardecer', 'gratuito', 'Gratuito', false, '/img/eventos/tema/iemanja.jpg', 'https://www.salvador.ba.gov.br', 'Colônia de Pescadores Z-1 / Prefeitura de Salvador', 'aprovado', '2026-08-24T12:00:00.000Z'),
  ('lavagem-do-bonfim-2027', 'Lavagem do Senhor do Bonfim 2027', 'Cortejo de 8 km com baianas de branco lavando as escadarias da Igreja do Bonfim, ao som de trios, afoxés e fanfarras.', 'Na segunda quinta-feira de janeiro, o cortejo parte da Igreja da Conceição da Praia, no Comércio, e segue até a Colina Sagrada, na Península de Itapagipe. As baianas lavam as escadarias da basílica com água de cheiro num dos maiores atos de fé e festa popular da Bahia.', 'cultura', 'presencial', 'salvador', 'Salvador', 'BA', 'Da Conceição da Praia à Igreja do Senhor do Bonfim', 'Largo do Bonfim - Bonfim', -12.9238, -38.5081, 'anual', '2027-01-14', null, 'Concentração às 7h; cortejo às 10h', 'gratuito', 'Gratuito', false, '/img/eventos/tema/bonfim.jpg', 'https://www.salvador.ba.gov.br', 'Prefeitura de Salvador', 'aprovado', '2026-08-25T12:00:00.000Z'),
  ('carnaval-olinda-2027', 'Carnaval de Olinda 2027', 'O Carnaval de rua mais tradicional do país: bonecos gigantes, frevo, maracatu e centenas de blocos gratuitos pelas ladeiras do Sítio Histórico.', 'Do sábado à terça de Carnaval, Olinda vira um só bloco. O cortejo dos Bonecos Gigantes, o Homem da Meia-Noite, a Corda e dezenas de troças e clubes de frevo tomam as ruas de pedra da cidade alta. Não há palcos fechados nem ingressos: a festa é toda na rua.', 'cultura', 'presencial', 'olinda', 'Olinda', 'PE', 'Sítio Histórico de Olinda', 'Carmo, Sé e Amparo - Olinda', -8.009, -34.843, 'anual', '2027-02-06', '2027-02-09', 'Blocos de manhã à noite', 'gratuito', 'Gratuito', false, '/img/eventos/tema/carnaval-olinda.jpg', 'https://www.olinda.pe.gov.br', 'Prefeitura de Olinda', 'aprovado', '2026-08-26T12:00:00.000Z'),
  ('forum-das-letras-ouro-preto-2026', 'Fórum das Letras de Ouro Preto 2026', 'Festival literário nas igrejas, teatros e casarões barrocos de Ouro Preto, com debates, lançamentos e itinerários literários.', 'Promovido pela UFOP, reúne escritores, tradutores, editores e leitores em mesas sobre literatura, história e cidadania, com programação nas Casas de Cultura, no Teatro Municipal e nas ladeiras da cidade. Datas de 2026 previstas para novembro — confirme no site oficial.', 'educacao', 'presencial', 'ouro-preto', 'Ouro Preto', 'MG', 'Centro Histórico de Ouro Preto', 'Praça Tiradentes e espaços culturais - Ouro Preto', -20.3853, -43.5036, 'anual', '2026-11-11', '2026-11-15', 'Mesas a partir das 9h', 'gratuito', 'Gratuito', false, '/img/eventos/tema/feira-livro.jpg', 'https://www.forumdasletras.ufop.br', 'Universidade Federal de Ouro Preto (UFOP)', 'aprovado', '2026-08-27T12:00:00.000Z')
